function shuffleOptions(q: SeedQuestion): { options: string[]; correctIndex: number; optionExplanations?: string[] } {
  const indices = q.options.map((_, i) => i);
  for (let i = indices.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [indices[i], indices[j]] = [indices[j], indices[i]];
  }
  return {
    options: indices.map((i) => q.options[i]),
    correctIndex: indices.indexOf(q.correctIndex),
    optionExplanations: q.optionExplanations ? indices.map((i) => q.optionExplanations![i]) : undefined,
  };
}

async function main() {
  for (const sys of systems) {
    const createdSystem = await prisma.system.upsert({
      where: { slug: sys.slug },
      update: { name: sys.name, description: sys.description, order: sys.order },
      create: {
        slug: sys.slug,
        name: sys.name,
        description: sys.description,
        order: sys.order,
      },
    });

    for (const topic of sys.topics) {
      const createdTopic = await prisma.topic.upsert({
        where: { slug: topic.slug },
        update: {
          name: topic.name,
          description: topic.description,
          order: topic.order,
          systemId: createdSystem.id,
        },
        create: {
          slug: topic.slug,
          name: topic.name,
          description: topic.description,
          order: topic.order,
          systemId: createdSystem.id,
        },
      });

      for (const q of topic.questions) {
        const { options, correctIndex, optionExplanations } = shuffleOptions(q);
        const data = {
          topicId: createdTopic.id,
          stem: q.stem,
          optionsJson: JSON.stringify(options),
          correctIndex,
          explanation: q.explanation,
          optionExplanationsJson: optionExplanations ? JSON.stringify(optionExplanations) : null,
          reference: q.reference ?? null,
          explanationImagesJson: q.explanationImages ? JSON.stringify(q.explanationImages) : null,
        };
        const existing = await prisma.question.findFirst({
          where: { topicId: createdTopic.id, stem: q.stem },
        });
        if (existing) {
          await prisma.question.update({ where: { id: existing.id }, data });
        } else {
          await prisma.question.create({ data });
        }
      }
    }
  }

  const totalQuestions = await prisma.question.count();
  const totalTopics = await prisma.topic.count();
  const totalSystems = await prisma.system.count();
  console.log(`Seeded ${totalSystems} systems, ${totalTopics} topics, and ${totalQuestions} questions.`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
